import {Vector3} from 'three';
export const strideWarpDefaults=()=>({enabled:false,parameter:'',scale:1,minScale:0,maxScale:3,source:'pose',mode:'planar',upAxis:[0,1,0],forwardAxis:[1,0,0]});
const fields=new Set(Object.keys(strideWarpDefaults())),axis=v=>Array.isArray(v)&&v.length===3&&v.every(n=>Number.isFinite(n)&&Math.abs(n)<=100000)&&Math.hypot(...v)>1e-8;
export function validStrideWarp(value){if(value===undefined)return true;if(!value||typeof value!=='object'||Array.isArray(value)||Object.keys(value).some(k=>!fields.has(k)))return false;const p={...strideWarpDefaults(),...value};if(typeof p.enabled!=='boolean'||typeof p.parameter!=='string'||p.parameter.length>160||!['pose','target'].includes(p.source)||!['planar','forward'].includes(p.mode)||![p.scale,p.minScale,p.maxScale].every(n=>Number.isFinite(n)&&n>=0&&n<=10)||p.minScale>p.maxScale||!axis(p.upAxis)||!axis(p.forwardAxis))return false;const u=new Vector3(...p.upAxis).normalize(),f=new Vector3(...p.forwardAxis).normalize();return p.mode!=='forward'||f.addScaledVector(u,-f.dot(u)).lengthSq()>1e-12;}
export class StrideWarpIK{
 constructor(solver){this.solver=solver;this.p={...strideWarpDefaults(),...solver.p.strideWarp};this.up=new Vector3(...this.p.upAxis).normalize();this.forward=new Vector3(...this.p.forwardAxis).normalize();this.forward.addScaledVector(this.up,-this.forward.dot(this.up)).normalize();this.delta=new Vector3();this.pose=new Vector3();this.original=new Vector3();this.goal=new Vector3();this.rotation=solver.targetRotation.clone();this.debug=solver.debug.stride={active:false,scale:1,mode:this.p.mode,source:this.p.source,target:[0,0,0],plantOverride:false};}
 warp(point,scale){const root=this.solver.positions[0];this.delta.copy(point).sub(root);if(this.p.mode==='planar')this.delta.addScaledVector(this.up,-this.delta.dot(this.up));else{const forward=this.delta.dot(this.forward);this.delta.copy(this.forward).multiplyScalar(forward);}return point.addScaledVector(this.delta,scale-1);}
 apply(weight){const s=this.solver,p=this.p,d=this.debug,value=p.parameter?s.owner.parameters.get(p.parameter):1;d.active=weight>0&&Number.isFinite(value);d.scale=d.active?Math.max(p.minScale,Math.min(p.maxScale,p.scale*value)):1;d.plantOverride=false;this.pose.copy(s.positions.at(-1));if(!d.active)return;this.original.copy(p.source==='pose'?this.pose:s.target);this.warp(this.pose,d.scale);s.target.copy(this.warp(this.original,d.scale));s.target.toArray(d.target);}
 plant(weight,frame){const s=this.solver;this.goal.copy(s.target);this.rotation.copy(s.targetRotation);const plant=s.footPlant.apply(s,weight,frame),d=s.debug.plant;this.debug.plantOverride=d.weight>0;if(d.missingAnchor)return 0;s.target.lerpVectors(this.goal,s.target,plant);s.targetRotation.slerp(this.rotation,1-plant);s.target.toArray(s.debug.target);return weight;}
}
export const strideWarpContract=Object.freeze({node:'twoBoneIK',property:'strideWarp optional; absent/disabled is legacy IK',fields:strideWarpDefaults(),control:'scale * optional Float parameter, clamped to minScale..maxScale; existing animGraphSetFloat/hb::AnimationGraph::SetFloat. Non-finite/missing runtime parameter bypasses warp.',space:'Component-space displacement from incoming root to foot/target. Normalized up removes vertical displacement; planar scales the full ground plane, forward scales only the projected forward component and preserves lateral stride.',order:'Warp raw pose/target before existing positionWeight, authored plant and ground projection. Ground pose rays follow the warped input foot; authored plant overrides warped goals. Alpha, segment length/stretch and joint limits still apply.',authoring:'Existing graph fields, typed folded editor, Float rename, validation/Undo/save and detached AI contract. Lazy solver-local scratch; no scene scans or per-frame vector allocation.',limits:['Authored scale only; no automatic speed estimation, gait phase or pelvis optimization','Unreachable targets retain IK reach and report residual error; no claim of physical contact simulation']});
